// Package carrier holds a citation followed by a separator word and a
// further parenthesized reference on the next comment line, so the
// qualifier of the anchor that replaces it absorbs the words behind the
// separator and reads that reference as the keyword and its member.
package carrier

// plan names the §4.8 workspace (lines 13-14) and
// egress (line 15) fields of the plan.
func plan() string { return "plan" }
